package cn.mop.api;
import cn.mop.domain.sla.*;
import cn.mop.domain.ticket.TicketLifecycle;
import cn.mop.domain.time.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class SlaClockStateTest {
    static final Instant T=Instant.parse("2026-10-20T00:00:00Z");
    static final String TENANT="10000000-0000-0000-0000-000000000001";
    private SlaClockCalculator.OpeningSnapshot opening(){return new SlaClockCalculator.OpeningSnapshot(SlaClockCalculator.Tier.STANDARD,SlaClockCalculator.Priority.P1,T,"frozen-config",Duration.ofSeconds(60),Duration.ofSeconds(120),null,null,null);}
    private TicketLifecycle.Snapshot row(long v,TicketLifecycle.State state,int second,Integer resolved,Integer closed){return new TicketLifecycle.Snapshot(TENANT,state,v,v>=4?1:0,T.plusSeconds(second),resolved==null?null:T.plusSeconds(resolved),closed==null?null:T.plusSeconds(closed),resolved==null?null:"a".repeat(64),closed==null?null:TicketLifecycle.CloseMode.CUSTOMER_CONFIRM,T.plusSeconds(60),T.plusSeconds(120));}
    private List<TicketLifecycle.Snapshot> cycle(){return List.of(row(1,TicketLifecycle.State.NEW,0,null,null),row(2,TicketLifecycle.State.IN_PROGRESS,10,null,null),row(3,TicketLifecycle.State.PENDING_CUSTOMER,30,30,null),row(4,TicketLifecycle.State.REOPENED,50,30,null));}
    @Test void newClockRunsWithoutInventedResponse(){var p=SlaClockState.project(opening(),List.of(cycle().get(0)),T.plusSeconds(20),null);assertEquals(SlaClockState.Status.RUNNING,p.response().status());assertEquals(Duration.ofSeconds(20),p.recovery().elapsed());assertNull(p.response().stoppedAt());}
    @Test void firstAcceptancePermanentlyStopsResponse(){var p=SlaClockState.project(opening(),cycle(),T.plusSeconds(60),SlaClockCalculator.ReopenPolicy.EXCLUDE_CONFIRMED_PAUSES);assertEquals(Duration.ofSeconds(10),p.response().elapsed());assertEquals(T.plusSeconds(10),p.response().stoppedAt());}
    @Test void customerWaitingPausesRecoveryAndDoesNotPretendFutureDeadline(){var p=SlaClockState.project(opening(),cycle().subList(0,3),T.plusSeconds(100),null);assertEquals(SlaClockState.Status.PAUSED,p.recovery().status());assertEquals(T.plusSeconds(30),p.pausedAt());assertEquals(Duration.ofSeconds(30),p.recovery().elapsed());assertNull(p.recovery().deadline());}
    @Test void missingReopenPolicyDoesNotResetOrGuess(){var p=SlaClockState.project(opening(),cycle(),T.plusSeconds(60),null);assertEquals("REOPEN_POLICY_MISSING",p.recovery().missing());assertNull(p.recovery().elapsed());assertEquals(SlaClockState.Status.COMPLETED,p.response().status());}
    @Test void excludedConfirmedWaitResumesOriginalBudget(){var p=SlaClockState.project(opening(),cycle(),T.plusSeconds(60),SlaClockCalculator.ReopenPolicy.EXCLUDE_CONFIRMED_PAUSES);assertEquals(Duration.ofSeconds(40),p.recovery().elapsed());assertEquals(T.plusSeconds(140),p.recovery().deadline());assertEquals(1,p.completedPauses().size());}
    @Test void explicitIncludeWaitPolicyDoesNotMoveDeadline(){var p=SlaClockState.project(opening(),cycle(),T.plusSeconds(60),SlaClockCalculator.ReopenPolicy.INCLUDE_ALL_ELAPSED_TIME);assertEquals(Duration.ofSeconds(60),p.recovery().elapsed());assertEquals(T.plusSeconds(120),p.recovery().deadline());}
    @Test void transferAndVendorWaitDoNotResetEitherClock(){var h=new ArrayList<>(cycle().subList(0,2));h.add(row(3,TicketLifecycle.State.IN_PROGRESS,20,null,null));h.add(row(4,TicketLifecycle.State.WAITING_VENDOR,30,null,null));var p=SlaClockState.project(opening(),h,T.plusSeconds(70),null);assertEquals(Duration.ofSeconds(70),p.recovery().elapsed());assertEquals(T.plusSeconds(120),p.recovery().deadline());}
    @Test void confirmedClockStopsAtResolutionNotConfirmation(){var h=new ArrayList<>(cycle().subList(0,3));h.add(row(4,TicketLifecycle.State.CLOSED,70,30,70));var p=SlaClockState.project(opening(),h,T.plusSeconds(100),null);assertEquals(SlaClockState.Status.COMPLETED,p.recovery().status());assertEquals(Duration.ofSeconds(30),p.recovery().elapsed());assertEquals(T.plusSeconds(30),p.recovery().stoppedAt());}
    @Test void closedThenReopenedRetainsOriginalClock(){var h=new ArrayList<>(cycle().subList(0,3));h.add(row(4,TicketLifecycle.State.CLOSED,70,30,70));h.add(row(5,TicketLifecycle.State.IN_PROGRESS,90,30,null));var p=SlaClockState.project(opening(),h,T.plusSeconds(100),SlaClockCalculator.ReopenPolicy.EXCLUDE_CONFIRMED_PAUSES);assertEquals(Duration.ofSeconds(40),p.recovery().elapsed());assertEquals(T.plusSeconds(180),p.recovery().deadline());}
    @Test void gapsFutureEventsAndIllegalTransitionsAreRejected(){assertThrows(IllegalArgumentException.class,()->SlaClockState.project(opening(),List.of(cycle().get(0),cycle().get(2)),T.plusSeconds(40),null));assertThrows(IllegalArgumentException.class,()->SlaClockState.project(opening(),cycle(),T.plusSeconds(40),null));assertThrows(IllegalArgumentException.class,()->SlaClockState.project(opening(),List.of(cycle().get(0),row(2,TicketLifecycle.State.WAITING_VENDOR,10,null,null)),T.plusSeconds(40),null));}
    @Test void storedDeadlineCannotDisagreeWithOpening(){var o=new SlaClockCalculator.OpeningSnapshot(SlaClockCalculator.Tier.STANDARD,SlaClockCalculator.Priority.P1,T,"changed",Duration.ofSeconds(61),Duration.ofSeconds(120),null,null,null);assertThrows(IllegalArgumentException.class,()->SlaClockState.project(o,List.of(cycle().get(0)),T.plusSeconds(20),null));}
    @Test void exactDeadlineIsNotAlreadyLateButFollowingInstantIs(){var h=List.of(cycle().get(0));assertFalse(SlaClockState.project(opening(),h,T.plusSeconds(60),null).response().breached());assertTrue(SlaClockState.project(opening(),h,T.plusSeconds(61),null).response().breached());}
    @Test void basicElapsedUsesOnlyPublishedWorkingWindows(){var calendar=new WorkingTime.CalendarData("published",1,new IntervalSets.Interval(T,T.plusSeconds(300)),List.of(new IntervalSets.Interval(T,T.plusSeconds(60)),new IntervalSets.Interval(T.plusSeconds(120),T.plusSeconds(240))),true);var o=new SlaClockCalculator.OpeningSnapshot(SlaClockCalculator.Tier.BASIC,SlaClockCalculator.Priority.P1,T,"frozen",Duration.ofSeconds(60),Duration.ofSeconds(120),calendar,null,null);var first=new TicketLifecycle.Snapshot(TENANT,TicketLifecycle.State.NEW,1,0,T,null,null,null,null,T.plusSeconds(60),T.plusSeconds(180));var p=SlaClockState.project(o,List.of(first),T.plusSeconds(90),null);assertEquals(Duration.ofSeconds(60),p.response().elapsed());assertTrue(p.response().breached());}
    @Test void outOfRangeDeadlineIsUnresolved(){var o=new SlaClockCalculator.OpeningSnapshot(SlaClockCalculator.Tier.STANDARD,SlaClockCalculator.Priority.P1,Instant.parse("9999-12-31T23:59:59Z"),"frozen",Duration.ofSeconds(10),Duration.ofSeconds(20),null,null,null);assertEquals("DEADLINE_OUT_OF_RANGE",SlaClockCalculator.initial(o).response().reason());}
}
